<div class="admin-stack"><div class="admin-page-head"><div><h1 class="admin-h1">内容迁移</h1></div><a class="btn btn-primary" href="<?= e(url_to('/admin/tools/transfer/export')) ?>">导出 JSON</a></div>
<div class="card admin-form-card"><form id="transferForm" method="post" enctype="multipart/form-data" action="<?= e(url_to('/admin/tools/transfer/import')) ?>"><?= csrf_field() ?><label class="admin-field"><span class="label">选择 JSON 文件</span><input class="input" type="file" name="file" accept="application/json,.json"></label><label class="admin-field"><span class="label">或粘贴 JSON</span><textarea class="input admin-input-block" name="json" rows="12" placeholder="粘贴导出的 pafish 内容包"></textarea></label><label class="admin-field"><span class="label">冲突策略</span><select class="input" name="mode"><option value="skip">已有别名跳过</option><option value="update">已有别名覆盖</option></select></label><button class="btn btn-primary" type="submit">导入内容</button><p id="transferMsg" class="admin-settings-msg" hidden></p></form></div></div>
<script>(function(){var f=document.getElementById('transferForm'),m=document.getElementById('transferMsg');f.addEventListener('submit',function(e){e.preventDefault();fetch(f.action,{method:'POST',body:new FormData(f)}).then(function(r){return r.json()}).then(function(j){m.textContent=j.ok?'导入完成：'+JSON.stringify(j.counts):j.error||'导入失败';m.hidden=false}).catch(function(){m.textContent='网络错误';m.hidden=false})})})();</script>
